# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: fold
def fold(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return fold(intake(render(emit(raw))))

